// A single-system teaching prototype. The other nine hardware models keep their explorer.
export const lessonSteps = [
  ['The big picture', 'Server ≠ GPU fabric'],
  ['Inside one server', 'Decode the NVIDIA diagram'],
  ['Follow the data', 'Choose a destination'],
  ['Place a training job', 'Connect it to Slurm']
];

const refs = {
  hardware: 'https://docs.nvidia.com/enterprise-reference-architectures/nvl72-ai-factory/latest/components.html',
  silicon: 'https://developer.nvidia.com/blog/inside-nvidia-blackwell-ultra-the-chip-powering-the-ai-factory-era/',
  scheduling: 'https://developer.nvidia.com/blog/unlock-exascale-performance-on-nvidia-gb200-nvl72-with-slurm-topology-aware-job-scheduling/',
  nccl: 'https://docs.nvidia.com/deeplearning/nccl/user-guide/docs/usage/collectives.html'
};
export const figures = {
  rack: { file: 'gb300-rack.png', title: 'The physical GB300 NVL72 rack', source: refs.hardware + '#figure-1', credit: 'NVIDIA Enterprise Reference Architecture · Figure 1', alt: 'NVIDIA rack diagram: 10 compute trays above 9 NVLink switch trays, 8 compute trays below, with power shelves and management switches.', note: 'Read the two compute sections together: 10 + 8 = 18 servers. The nine NVLink switch trays connect their GPUs. The switches at the very top are management switches.' },
  tray: { file: 'gb300-tray.png', title: 'The compute tray, as NVIDIA draws it', source: refs.hardware + '#figure-3', credit: 'NVIDIA Enterprise Reference Architecture · Figure 3', alt: 'NVIDIA compute-tray wiring: two Grace CPUs, each between two Blackwell Ultra GPUs; CLinks joins the CPUs. Four ConnectX-8 adapters, a BlueField-3 DPU, and NVMe drives occupy the I/O paths below.', note: 'The purple C2C links connect CPUs to GPUs. The green CLinks line joins the CPUs. Rack-wide GPU peer NVLink is omitted from this I/O figure; the yellow and orange paths are PCIe. Small selection handles are present in NVIDIA’s published original.' },
  gpu: { file: 'blackwell-ultra.webp', title: 'Two compute dies form one GPU', source: refs.silicon, credit: 'NVIDIA Technical Blog · Blackwell Ultra, Figure 1', alt: 'NVIDIA Blackwell Ultra silicon diagram: two compute dies linked by NV-HBI, with HBM controllers and separate NVLink and NVLink-C2C interfaces.', note: 'Both halves are one CUDA accelerator. The 288 GB HBM figure is an architecture maximum; SKU capacities vary. The 1,800 GB/s NVLink and 900 GB/s C2C figures sum both directions. HBM’s 8 TB/s keeps its published memory-interface convention.' }
};
const sourceLink = (url, text) => `<a href="${url}" target="_blank" rel="noopener noreferrer">${text} ↗<span class="sr-only"> (opens in a new tab)</span></a>`;
const figure = (key, compact = false) => {
  const f = figures[key];
  return `<figure class="nvidia-figure ${compact ? 'compact-figure' : ''}"><div class="figure-topline"><span>NVIDIA’S DIAGRAM</span><button id="enlarge-${key}" data-figure="${key}" aria-label="Enlarge ${f.title}">Enlarge ↗</button></div><button class="figure-image-button" data-figure="${key}" aria-label="Enlarge ${f.title}"><img src="./assets/nvidia/${f.file}" alt="${f.alt}"></button><figcaption>${sourceLink(f.source, f.credit)}<p>${f.note}</p></figcaption></figure>`;
};
export function figureDialog(key) {
  const f = figures[key];
  return `<p>${f.note}</p><div class="figure-full"><img src="./assets/nvidia/${f.file}" alt="${f.alt}"></div><p class="figure-credit">© NVIDIA · ${sourceLink(f.source, f.credit)}. Unmodified original; scroll horizontally if needed to read the labels.</p>`;
}

function gpuCells(start = 0, ranks = false) {
  return `<div class="lesson-gpus">${Array.from({ length: 4 }, (_, i) => `<span class="lesson-gpu"><b>${ranks ? `Rank ${start + i}` : `GPU ${i}`}</b><small>${ranks ? `GPU ${i} · local HBM` : 'local HBM'}</small></span>`).join('')}</div>`;
}
function server(label, options = {}) {
  return `<div class="lesson-server"><div class="server-label"><strong>${label}</strong><span>${options.ranks ? '4 processes · 4 GPUs' : 'one server / OS'}</span></div><div class="lesson-host">2 Grace CPUs <span>+ their host memory</span></div>${gpuCells(options.start, options.ranks)}</div>`;
}
const takeaway = (label, text) => `<div class="lesson-takeaway"><span>${label}</span><p>${text}</p></div>`;

function overview() {
  return `<div class="overview-grid"><section class="logical-stage" aria-label="Logical view of the rack"><div class="stage-heading"><span class="eyebrow">THE LOGICAL VIEW</span><span>One NVL72 rack</span></div><div class="rack-domain"><div class="domain-caption"><span class="domain-dot"></span>72 GPUs in one NVLink domain</div><div class="overview-servers"><button id="open-server" class="server-open" data-lesson="1" aria-label="Look inside compute node 01">${server('Compute node 01 ↗')}</button>${server('Compute node 02')}</div><div class="fabric-branches" aria-hidden="true"><i></i><i></i></div><div class="lesson-fabric"><strong>NVLink switch fabric</strong><span>9 switch trays · 18 NVSwitch chips</span></div><div class="more-servers"><span aria-hidden="true">↑</span><strong>16 more servers connect here too</strong><span>Each adds 4 GPUs and 2 CPUs</span></div></div><p class="stage-caption">Simplified connectivity. Every GPU connects to the switch fabric; the lines group connections for readability.</p></section>${figure('rack', true)}</div>${takeaway('THE IDEA TO KEEP', 'A <strong>node</strong> is a server boundary. An <strong>NVLink domain</strong> is a GPU communication boundary. Here, that fabric crosses all 18 nodes.')}<div class="lesson-equation"><span><b>4</b> GPUs per node</span><i>×</i><span><b>18</b> nodes</span><i>=</i><span><b>72</b> connected GPUs</span></div>`;
}

const lenses = {
  groups: { label: 'CPU + GPU groups', title: 'Find the two repeated GPU–CPU–GPU groups.', text: 'Each group is a GB300 superchip: one Grace CPU with two Blackwell Ultra GPUs. Two groups make this four-GPU server. The CLinks line across the top joins the two CPUs.', hint: 'Purple arrows = NVLink-C2C, the coherent CPU–GPU connection.', zones: '<span style="left:1%;top:10%;width:33%;height:18%"></span><span style="left:37%;top:10%;width:34%;height:18%"></span>' },
  network: { label: 'Compute networking', title: 'Find the four orange CX-8 boxes.', text: 'These are the ConnectX-8 compute adapters. They provide the GPU network path beyond this rack’s NVLink domain. The yellow GPU-to-adapter connections are PCIe, not NVLink.', hint: 'Follow the downward 800 Gbps arrows to the external compute network.', zones: '<span style="left:14%;top:51%;width:16%;height:26%"></span><span style="left:42%;top:51%;width:16%;height:26%"></span>' },
  storage: { label: 'Storage + control', title: 'Find the BlueField DPU and the blue storage boxes.', text: 'BlueField handles the storage and user/control network in this reference. The blue M.2 and NVMe boxes are persistent local storage. Their capacity is separate from CPU RAM and GPU HBM.', hint: 'This I/O diagram leaves out the rack-wide GPU NVLink fabric.', zones: '<span style="left:68%;top:32%;width:7%;height:40%"></span><span style="left:8%;top:79%;width:55%;height:12%"></span>' }
};
function inside(state) {
  const lens = lenses[state.lens] || lenses.groups;
  return `<div class="node-recipe"><span><b>1 GB300 superchip</b><small>1 Grace CPU + 2 GPUs</small></span><i>× 2</i><span><b>1 compute node</b><small>2 CPUs + 4 GPUs</small></span><i>× 18</i><span><b>1 NVL72 rack</b><small>36 CPUs + 72 GPUs</small></span></div><section class="diagram-lesson" aria-label="Guided reading of NVIDIA compute tray diagram"><div class="lesson-controls" aria-label="Choose a part of the tray">${Object.entries(lenses).map(([key, l], i) => `<button id="lens-${key}" data-lens="${key}" aria-pressed="${key === state.lens}" class="${key === state.lens ? 'active' : ''}"><span>0${i + 1}</span>${l.label}</button>`).join('')}</div><div class="diagram-reading" aria-live="polite"><h2>${lens.title}</h2><p>${lens.text}</p></div><p class="tray-scroll-hint">Wide wiring diagram · scroll sideways to follow the connections, or enlarge it below.</p><div class="tray-scroll" tabindex="0" aria-label="NVIDIA tray diagram; scroll horizontally on small screens"><div class="tray-annotated"><img src="./assets/nvidia/gb300-tray.png" alt="${figures.tray.alt}"><div class="figure-highlights" aria-hidden="true">${lens.zones}</div></div></div><div class="diagram-reading-footer"><p>${lens.hint}</p><button id="enlarge-tray" data-figure="tray">Enlarge original ↗</button></div><p class="figure-credit">© NVIDIA · ${sourceLink(figures.tray.source, figures.tray.credit)} · Outlines added by this learning tool.</p></section>${takeaway('THE MISSING CONNECTION', 'The GPUs also connect to the <strong>rack’s NVLink switches</strong>. NVIDIA’s tray figure above emphasizes CPU and peripheral I/O; it does not draw that peer-GPU path.')}<details class="silicon-detail"><summary>Go one level deeper: what counts as one GPU?</summary><div class="silicon-grid">${figure('gpu')}<div><h2>Two dies. One CUDA device.</h2><p>A Blackwell Ultra GPU contains two compute dies joined internally by NV-HBI. They work as a single GPU with its own HBM.</p><p>That means four GPU packages in a node are still <strong>four accelerators</strong>. A superchip combines a CPU with two of these GPUs.</p><button data-explore="gpu" class="lesson-link">Explore GPU memory and interfaces →</button></div></div></details>`;
}

const paths = {
  memory: { label: 'Its own HBM', question: 'The tensor is in this GPU’s memory.', title: 'The access stays local to one GPU.', steps: [['Local HBM3e', 'This GPU’s weights / working data', 'memory'], ['Memory controllers', 'On the GPU', 'memory'], ['GPU compute', 'One CUDA accelerator', 'gpu']], impact: 'Kernel execution repeatedly reads and writes local HBM. Allocating a tensor on a different GPU changes which communication path is needed.', rate: 'Up to 8 TB/s', scope: 'Published HBM bandwidth · one GPU', caveat: 'Memory-interface convention. This is not a bidirectional link sum and is not doubled.', source: refs.silicon },
  host: { label: 'CPU memory', question: 'The tensor is in the paired Grace CPU’s memory.', title: 'Host access uses NVLink-C2C.', steps: [['Grace + LPDDR5X', 'Paired CPU’s physical memory', 'cpu'], ['NVLink-C2C', 'Coherent CPU–GPU interface', 'cpu'], ['Paired GPU', 'Separate local HBM', 'gpu']], impact: 'Coherent access does not make CPU memory as local or as fast as GPU HBM. Where the working set lives still matters.', rate: '450 GB/s', scope: 'One-direction equivalent · CPU–GPU interface/group', caveat: '900 GB/s published send + receive budget. Do not assign that full rate to every drawn GPU branch; host memory can also limit a transfer.', source: refs.silicon },
  peer: { label: 'Another node, same rack', question: 'The tensor must reach a GPU in another node of this rack.', title: 'Crossing a server boundary can still use NVLink.', steps: [['GPU · node 01', 'Source GPU and its HBM', 'gpu'], ['NVLink → NVSwitch → NVLink', 'Rack-wide scale-up fabric', 'fabric'], ['GPU · node 02', 'Destination GPU and its HBM', 'gpu']], impact: 'These processes can run on different servers while their GPUs communicate through the same NVLink domain. The payload need not pass through CPU RAM or the external compute network.', rate: '900 GB/s', scope: 'Per GPU · each direction · shared across peers', caveat: '1.8 TB/s published send + receive interface budget. This is not a dedicated 900 GB/s link to each of the other 71 GPUs.', source: refs.hardware + '#nvidia-nvlink-switch-tray' },
  remote: { label: 'A different rack', question: 'The tensor must reach a GPU in a different rack.', title: 'Now the transfer uses the compute network.', steps: [['GPU · rack A', 'Source GPU and its HBM', 'gpu'], ['ConnectX-8 → network → ConnectX-8', 'External InfiniBand or Ethernet fabric', 'network'], ['GPU · rack B', 'A separate NVLink domain', 'gpu']], impact: 'GPUDirect RDMA can carry GPU data without staging it in host RAM. Adding racks adds a different communication tier; it does not automatically enlarge the NVLink domain.', rate: '100 GB/s', scope: 'Per compute endpoint · each direction · before overhead', caveat: '800 Gb/s ÷ 8 = 100 GB/s. This is a line-rate ceiling, not application throughput or a guarantee that one flow reaches it.', source: refs.hardware }
};
function transfers(state) {
  const p = paths[state.storyPath] || paths.peer;
  return `<section class="transfer-lesson"><div class="destination-label">Where does the data need to go?</div><div class="destination-options" aria-label="Data destination">${Object.entries(paths).map(([key, path]) => `<button id="destination-${key}" data-story-path="${key}" aria-pressed="${state.storyPath === key}" class="${state.storyPath === key ? 'active' : ''}">${path.label}</button>`).join('')}</div><div class="transfer-result" aria-live="polite"><p class="transfer-question">${p.question}</p><h2>${p.title}</h2><div class="route-picture ${state.storyPath}" aria-label="Illustrative data route">${p.steps.map(([title, sub, kind], i) => `${i ? '<span class="route-arrow" aria-hidden="true">→</span>' : ''}<div class="route-stop ${kind}"><strong>${title}</strong><span>${sub}</span></div>`).join('')}</div><div class="transfer-details"><div><h3>What this means for your code</h3><p>${p.impact}</p></div><div class="path-budget"><strong>${p.rate}</strong><span>${p.scope}</span><p>${p.caveat}</p></div></div><p class="figure-credit">Logical path, not exact routing or measured performance. ${sourceLink(p.source, 'NVIDIA reference')}</p></div></section>${takeaway('BEFORE COMPARING BANDWIDTH', 'Ask <strong>which endpoints, which interface, and which direction?</strong> A rack-wide sum cannot tell you how fast one tensor moves.')}<button class="lesson-link" data-explore="cluster">Inspect the full network and component specifications →</button>`;
}

function placement(state) {
  const split = state.placement === 'split';
  return `<section class="job-lesson"><div class="job-setup"><div><span class="eyebrow">A CONCRETE EXAMPLE</span><h2>8 training processes. One GPU each.</h2><p>Assume two whole four-GPU nodes and one process per GPU. “Rank” is the process’s identity in this example, not a physical chip number.</p></div><div class="allocation-summary"><b>2 nodes × 4 GPUs</b><span>= 8 GPUs / 8 ranks</span></div></div><div class="placement-switch" aria-label="Example job placement"><button id="placement-same" data-placement="same" aria-pressed="${!split}" class="${!split ? 'active' : ''}">Both nodes in one rack</button><button id="placement-split" data-placement="split" aria-pressed="${split}" class="${split ? 'active' : ''}">One node in each rack</button></div><div class="allocation-result" aria-live="polite"><div class="job-placement ${split ? 'split' : 'same'}"><div class="placement-domain"><span class="placement-domain-label">RACK A · NVLINK DOMAIN A</span>${server('Node 01', {ranks:true, start:0})}${!split ? server('Node 02', {ranks:true, start:4}) : ''}<div class="job-fabric">NVLink switch fabric</div></div>${split ? `<div class="between-domains"><b>ConnectX-8</b><span>↕</span><strong>Compute network</strong><span>↕</span><b>ConnectX-8</b></div><div class="placement-domain"><span class="placement-domain-label">RACK B · NVLINK DOMAIN B</span>${server('Node 01', {ranks:true, start:4})}<div class="job-fabric">NVLink switch fabric</div></div>` : ''}</div><div class="placement-verdict"><span class="eyebrow">SAME GPU COUNT · DIFFERENT CONNECTIVITY</span><h3>${split ? 'Rank 0 → rank 4 now crosses the compute network.' : 'Rank 0 → rank 4 can stay on the NVLink fabric.'}</h3><p>${split ? 'The allocation still has eight GPUs. Communication between the two nodes crosses NVLink-domain boundaries and uses their compute adapters.' : 'The ranks live on different servers, but all eight GPUs belong to the same NVLink domain. The other 64 GPUs in the rack are outside this example allocation.'}</p></div></div><p class="lesson-note">Illustrative placement, not a scheduler simulation. A two-node request alone does not guarantee rack locality; cluster configuration, availability, and topology policy determine the actual allocation.</p></section><div class="training-bridge"><div><span class="eyebrow">DURING TRAINING</span><h2>A collective is a communication operation.</h2><p>For example, an AllReduce combines values from the participating GPUs and returns the result to each rank. Its communication crosses whichever hardware boundaries the job occupies.</p><p>Real NCCL algorithms can use multiple paths and offloads. The example shows the boundary that changes, not a predicted collective route or runtime.</p></div><div><span class="eyebrow">FROM YOUR SLURM MENTAL MODEL</span><p><strong>The scheduler allocates nodes and GPUs.</strong> Your launcher creates processes; the training framework gives them work and coordinates communication.</p><p><strong>Placement is part of the architecture.</strong> When diagnosing a job, ask where its GPUs are, not only how many it received.</p></div></div><p class="lesson-sources">Read the mechanism: ${sourceLink(refs.scheduling, 'NVIDIA on Slurm topology and GB200/GB300 node grouping')} · ${sourceLink(refs.nccl, 'NCCL collective operations')}</p><details class="knowledge-check"><summary>Check your understanding: does an 8-GPU allocation imply one NVLink domain?</summary><p><strong>No.</strong> Eight GPUs may occupy two nodes in the same rack or nodes in separate racks. You need the actual placement to know whether inter-node GPU traffic can remain on the local NVLink fabric.</p></details>`;
}

export function learningPage(state) {
  const step = Math.max(0, Math.min(3, state.lesson));
  const titles = ['18 servers.<br><em>One GPU fabric.</em>', 'A server is built from<br><em>two CPU–GPU groups.</em>', 'The destination<br><em>determines the path.</em>', 'Same GPU count.<br><em>Different placement.</em>'];
  const intros = ['You already know what a cluster node is. The new idea in GB300 NVL72 is that the fast GPU fabric extends across 18 of those nodes.', 'Read NVIDIA’s tray diagram in layers. Start with the processors, then trace the network and storage connections.', 'Start with one tensor. Its location and destination determine which part of the architecture carries the data.', 'Connect the hardware to a distributed training job. Move the same eight ranks and see which boundary changes.'];
  return `<div class="lesson-topline"><span>GB300 NVL72 <span class="lesson-edition">/ BLACKWELL ULTRA</span></span><span>0${step + 1} / 04</span></div><header class="lesson-intro"><h1 id="learning-title" tabindex="-1">${titles[step]}</h1><p>${intros[step]}</p></header>${[overview, inside, transfers, placement][step](state)}<nav class="lesson-pagination" aria-label="Lesson navigation">${step ? `<button id="lesson-prev" data-lesson="${step - 1}">← ${lessonSteps[step - 1][0]}</button>` : '<span class="lesson-duration">Four ideas, one architecture.</span>'}${step < 3 ? `<button id="lesson-next" class="lesson-next" data-lesson="${step + 1}">${lessonSteps[step + 1][0]} <span>→</span></button>` : '<button id="lesson-finish" class="lesson-next" data-explore="rack">Explore the hardware <span>→</span></button>'}</nav><footer class="lesson-footer"><span>NVIDIA Enterprise reference · logical teaching views<br>Diagrams © NVIDIA · references checked November 2, 2026</span><button data-dialog="notes">Configuration & number notes ↗</button></footer>`;
}
